window.AUTH=window.AUTH||{};window.AUTH["25-966"]={"d":"25-966","id":"2026/25-966","n":"Department of Labor v. Sun Valley Orchards, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioners Department of Labor, et al.","date":"2026-06-18","url":"https://www.supremecourt.gov/DocketPDF/25/25-966/413619/20260618153112527_25-966SunValleyGovtBr_with_Appendix.pdf","side":"pet","n":100},{"k":"respondent","label":"Brief of respondent Sun Valley Orchards","date":"2026-07-27","url":"https://www.supremecourt.gov/DocketPDF/25/25-966/417327/20260727112239225_25-966%20Brief%20of%20Respondent.pdf","side":"res","n":87},{"k":"reply","label":"Reply of petitioners Department of Labor, et al.","date":"2026-08-26","url":"https://www.supremecourt.gov/DocketPDF/25/25-966/420181/20260826141240821_25-966%20Sun%20Valley%20Reply.pdf","side":"pet","n":52}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"by":{"0":"24, 40"}},{"t":"case","label":"Allman v. United States","cite":"131 U.S. 31","y":1889,"id":"scdb/1888-219","sc":1,"by":{"0":"31, 38, 39","1":"39","2":"9, 12, 19"},"q":[{"src":"argument","who":"Justice Jackson","text":"I mean, we have Oceanic Steam, Lloyd Sabaudo, Helvering, Allman, McGrath, Origet. All these cases had monetary liability being imposed by the government, and we found the public rights exception applied."}]},{"t":"case","label":"Appleby v. City of New York","cite":"271 U.S. 364","y":1926,"id":"scdb/1925-169","sc":1,"by":{"0":"27"}},{"t":"case","label":"Axon Enterprise, Inc. v. FTC","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"by":{"0":"30"}},{"t":"case","label":"Bartlett v. Kane","cite":"16 How. 263","y":1854,"url":"https://www.courtlistener.com/c/How./16/263/","by":{"0":"28, 39","2":"9, 19"},"q":[{"src":"brief","b":0,"text":"the ordinary duties of the executive departments.","cite":"16 How. 263, 272"}]},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"since the beginning of the Republic.","cite":"569 U.S. 290, 305 n.4"}]},{"t":"case","label":"Cross v. Harrison","cite":"16 How. 164","y":1854,"url":"https://www.courtlistener.com/c/How./16/164/","by":{"0":"31"}},{"t":"case","label":"Department of State v. Muñoz","cite":"602 U.S. 899","y":2024,"url":"https://supreme.justia.com/cases/federal/us/602/899/","sc":1,"by":{"0":"18","2":"18, 21"},"q":[{"src":"brief","b":0,"text":"From the beginning, the admission of noncitizens into the country was characterized as ‘of favor and not of right.’","cite":"602 U.S. 899, 912"}]},{"t":"case","label":"Fong Yue Ting v. United States","cite":"149 U.S. 698","y":1893,"id":"scdb/1892-256","sc":1,"by":{"0":"29","1":"28"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"-- because we've had plenty of cases, Fong Yue Ting, where an alien was here for years, and we said you can deport him in administrative process, correct?"}]},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 858","y":1991,"id":"1990/90-762","sc":1,"by":{"0":"25"}},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"by":{"0":"29, 39","2":"9, 12"},"q":[{"src":"argument","who":"Justice Jackson","text":"I mean, we have Oceanic Steam, Lloyd Sabaudo, Helvering, Allman, McGrath, Origet. All these cases had monetary liability being imposed by the government, and we found the public rights exception applied."}]},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"0":"21"}},{"t":"case","label":"Hispanic Affairs Project v. Acosta","cite":"901 F.3d 378","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/901/378/","by":{"0":"8"}},{"t":"case","label":"Karnuth v. United States ex rel. Albro","cite":"279 U.S. 231","y":1929,"id":"scdb/1928-092","sc":1,"by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"to protect American labor against the influx of foreign labor.","cite":"279 U.S. 231, 243"}]},{"t":"case","label":"Keller v. United States","cite":"213 U.S. 138","y":1909,"id":"scdb/1908-117","sc":1,"by":{"0":"34"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"by":{"0":"34","1":"28"}},{"t":"case","label":"Learning Resources, Inc. v. Trump","cite":"146 S. Ct. 628","y":2026,"id":"2025/24-1287","sc":1,"by":{"0":"31"}},{"t":"case","label":"Lem Moon Sing v. United States","cite":"158 U.S. 538","y":1895,"id":"scdb/1894-233","sc":1,"by":{"0":"3, 34","1":"28"},"q":[{"src":"brief","b":0,"text":"[t]he power of Congress to exclude aliens altogether from the United States, or to prescribe the terms and conditions upon which they may come to this country, and to have its declared policy in that regard enforced exclusively through executive officers, without judicial intervention, is settled by [the Court’s] previous adjudications.","cite":"158 U.S. 538, 547"}]},{"t":"case","label":"Lloyd Sabaudo Societa Anonima per Azioni v. Elting","cite":"287 U.S. 329","y":1932,"id":"scdb/1932-015","sc":1,"by":{"0":"5, 18, 33, 34, 39","1":"29, 30, 31","2":"7, 9, 10"},"q":[{"src":"argument","who":"Ms. Harris","text":"Indeed, Oceanic Steam and Lloyd Sabaudo upheld near- identical remedies a century ago in similar circumstances. Respondent instead argues that only courts can adjudicate civil penalties."},{"src":"argument","who":"Ms. Harris","text":"There are plenty of civil penalties in the immigration context both for the aliens themselves for violating the conditions of admission to the United States, there are civil penalties throughout the INA, and for people like transport carriers in Oceanic Steam or Lloyd Sabaudo, who violate the conditions on transporting aliens to the United States."},{"src":"argument","who":"Justice Jackson","text":"I mean, we have Oceanic Steam, Lloyd Sabaudo, Helvering, Allman, McGrath, Origet. All these cases had monetary liability being imposed by the government, and we found the public rights exception applied."}]},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"by":{"0":"11, 21, 42","1":"51"},"q":[{"src":"brief","b":0,"text":"especially useful in determining the statute’s meaning.","cite":"603 U.S. 369, 386, 394"}]},{"t":"case","label":"McElrath v. United States","cite":"102 U.S. 426","y":1880,"id":"scdb/1880-047","sc":1,"by":{"0":"3, 31, 39","1":"39","2":"10, 12, 19"},"q":[{"src":"brief","b":0,"text":"avails himself of the privilege thus granted, he must do so subject to the conditions annexed by the government to the exercise of the privilege.","cite":"102 U.S. 426, 440"},{"src":"brief","b":2,"text":"must do so subject to the conditions annexed by the government,","cite":"102 U.S. at 440"},{"src":"argument","who":"Mr. Johnson","text":"So, for instance, just to pick one, the government cites McElrath, which is a case about the dispute between the government and a government employee and whether the Court of Claims could adjudicate counterclaims, and it's about -- the case is about the importance of the government's sovereign immunity, that, you know, there's particular considerations --"}]},{"t":"case","label":"Murray’s Lessee v. Hoboken Land & Improvement Co.","cite":"18 How. 272","y":1856,"url":"https://www.courtlistener.com/c/How./18/272/","by":{"0":"2, 25, 26, 28, 39","2":"2, 7, 12, 19"}},{"t":"case","label":"NLRB v. J.H. Rutter-Rex Manufacturing Co.","cite":"396 U.S. 258","y":1969,"id":"1969/32","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"the status quo that would have obtained 4 Because the administrative imposition of civil penalties under Section 1188(g)(2) complies with Article III, see pp. 24-45, infra, this Court need not consider here whether Section 2461 would apply if a statute authorizes administrative imposition of penalties but that authorization is held unconstitutional. but for the wrongful act.","cite":"396 U.S. 258, 265"}]},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"by":{"0":"6, 29, 36","1":"28"},"q":[{"src":"brief","b":0,"text":"as inherent in sovereignty, and essential to self-preservation, to forbid the entrance of foreigners within its dominions, or to admit them only in such cases and upon such conditions as it may see fit to prescribe.","cite":"142 U.S. 651, 659"},{"src":"brief","b":0,"text":"to admit [aliens] only in such cases and upon such conditions as it may see fit to prescribe.","cite":"142 U.S. at 659"}]},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"by":{"0":"4, 5, 18, 19, 33, 36, 38-41, 43","1":"3, 15, 26, 27, 29, 30, 31, 37","2":"9, 11, 12, 15-18, 21"},"q":[{"src":"brief","b":0,"text":"without the necessity of invoking the judicial power.","cite":"214 U.S. 320, 339, 342"},{"src":"brief","b":0,"text":"Congress has the power to exclude aliens from the United States; to prescribe the terms and conditions on which they may come in; * * * and to commit the enforcement of such conditions and regulations to executive officers.","cite":"214 U.S. at 335"},{"src":"brief","b":1,"text":"provide for the examination of the alien by medical officers, and [ ] attach conclusive effect to the result of that examination for the purposes of exclusion or deportation.","cite":"214 U.S. at 342"},{"src":"brief","b":2,"text":"requir[e] the exercise of judicial authority,","cite":"214 U.S. at 343"},{"src":"argument","who":"Ms. Harris","text":"Indeed, Oceanic Steam and Lloyd Sabaudo upheld near- identical remedies a century ago in similar circumstances. Respondent instead argues that only courts can adjudicate civil penalties."},{"src":"argument","who":"Ms. Harris","text":"There are plenty of civil penalties in the immigration context both for the aliens themselves for violating the conditions of admission to the United States, there are civil penalties throughout the INA, and for people like transport carriers in Oceanic Steam or Lloyd Sabaudo, who violate the conditions on transporting aliens to the United States."},{"src":"argument","who":"Chief Justice Roberts","text":"Have the -- it -- it's -- the Oceanic Steam had to do very much with entry, a condition of entry, and loathsome diseases. This strikes me as significantly different in terms of you're -- you're trying to leverage an entry several weeks, months, in the -- in the past to the particular condition of work that doesn't seem to have much to do with the actual entry itself other than getting the person there."}]},{"t":"case","label":"Oil States Energy Services, LLC v. Greene’s Energy Group, LLC","cite":"584 U.S. 325","y":2018,"id":"2017/16-712","sc":1,"by":{"0":"26, 27, 30, 31, 43","1":"2, 34, 35, 47","2":"7, 14, 20"},"q":[{"src":"brief","b":0,"text":"add to the ‘various formulations’ of the public-rights doctrine","cite":"584 U.S. at 334"},{"src":"brief","b":0,"text":"need not consider whether [the agency adjudications at issue] would be constitutional ‘without any sort of intervention by a court at any stage of the proceedings.’","cite":"584 U.S. at 344"},{"src":"brief","b":1,"text":"from their nature do not require judicial determination.","cite":"584 U.S. 325, 334"},{"src":"brief","b":2,"text":"[t]hat Congress chose the courts in [the statute in Hepner] does not foreclose its choice of [an agency] today.","cite":"584 U.S. at 342"}]},{"t":"case","label":"Origet v. Hedden","cite":"155 U.S. 228","y":1894,"id":"scdb/1894-025","sc":1,"by":{"0":"28, 39","2":"9"},"q":[{"src":"argument","who":"Justice Jackson","text":"I mean, we have Oceanic Steam, Lloyd Sabaudo, Helvering, Allman, McGrath, Origet. All these cases had monetary liability being imposed by the government, and we found the public rights exception applied."}]},{"t":"case","label":"Passavant v. United States","cite":"148 U.S. 214","y":1893,"id":"scdb/1892-141","sc":1,"by":{"0":"28, 39, 41","1":"38","2":"9"}},{"t":"case","label":"Phillips v. Commissioner","cite":"283 U.S. 589","y":1931,"id":"scdb/1930-077","sc":1,"by":{"0":"29, 39","1":"40"}},{"t":"case","label":"SEC v. Jarkesy","cite":"603 U.S. 109","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/109/","sc":1,"by":{"0":"2, 3, 5, 17, 18, 21, 26, 27, 29, 34-36, 38, 40, 42","1":"1, 2, 3, 4, 13, 14, 15, 17, 21, 22, 23, 24, 25, 27, 30, 32, 33, 37, 43, 44","2":"1, 8, 11-13, 15, 18, 20, 21, 23"},"q":[{"src":"brief","b":0,"text":"the stuff of the traditional actions at common law tried by the courts at Westminster in 1789","cite":"603 U.S. 109, 128"},{"src":"brief","b":0,"text":"has not ‘definitively explained’ the distinction between public and private rights,","cite":"603 U.S. at 131"},{"src":"brief","b":1,"text":"If a suit is in the nature of an action at common law, then the matter presumptively concerns private rights, and adjudication by an Article III court is mandatory.","cite":"603 U.S. 109, 128"},{"src":"brief","b":1,"text":"[E]ven with respect to matters that arguably fall within the scope of the ‘public rights’ doctrine, the presumption is in favor of Article III courts.","cite":"603 U.S. at 132"},{"src":"brief","b":2,"text":"effectively decide[d] that th[e] suit implicate[d] the Seventh Amendment.","cite":"603 U.S. at 127"},{"src":"brief","b":2,"text":"operate[d] pursuant to similar legal principles.","cite":"603 U.S. at 134"}]},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"591 U.S. 197","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/197/","sc":1,"by":{"0":"25, 26"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"by":{"0":"27"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"by":{"0":"25, 26","1":"1, 17, 21, 35, 36, 39, 40, 41","2":"21, 22"},"q":[{"src":"brief","b":1,"text":"the stuff of the traditional actions at common law.","cite":"564 U.S. 462, 484"},{"src":"brief","b":1,"text":"could only be brought if the Federal Government chose to allow it by waiving sovereign immunity.","cite":"564 U.S. at 489"},{"src":"argument","who":"Mr. Johnson","text":"So, you know, I don't disagree that immigration is part of what's going on here, but I think, under that theory or under that sort of description, that the claims at issue in Stern would have been bankruptcy claims."}]},{"t":"case","label":"Sturges v. Crowninshield","cite":"4 Wheat. 122","y":1819,"url":"https://www.courtlistener.com/c/Wheat./4/122/","by":{"0":"37"}},{"t":"case","label":"Tappan v. United States","cite":"23 F. Cas. 690","y":1822,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./23/690/","by":{"0":"28, 31","1":"38"},"q":[{"src":"brief","b":0,"text":"conditions upon which the importation shall be permitted.","cite":"23 F. Cas. at 691"}]},{"t":"case","label":"Thomas v. Union Carbide Agricultural Products Co.","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"by":{"0":"31","1":"21, 44, 47","2":"19"}},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"by":{"0":"38","1":"22, 27"},"q":[{"src":"argument","who":"Justice Kavanaugh","text":"On the question of civil penalties and this Court's precedent, in Tull, we said at 422 -- and this is 40 years ago -- a civil penalty was a type of remedy at common law that could only be enforced in courts of law."},{"src":"argument","who":"Ms. Harris","text":"I think Tull is easily reconcilable with the rest of what Jarkesy did, including quoting the part of Oceanic Steam about civil penalties in the immigration context, because Tull is a case that says you're basically in step 1 of Jarkesy."},{"src":"argument","who":"Mr. Johnson","text":"And so the Court, in -- in Tull, as Justice Kavanaugh was suggesting, said that penalties were always a traditional remedy at common law. And I think back wages also are a traditional common law -- or even if not -- I think there's a dispute between the parties, are they legal or equitable?"}]},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"by":{"0":"25"}},{"t":"case","label":"United States v. Ju Toy","cite":"198 U.S. 253","y":1905,"id":"scdb/1904-086","sc":1,"by":{"0":"34","1":"28"}},{"t":"case","label":"United States v. New York & Cuba Mail Steamship Co.","cite":"269 U.S. 304","y":1925,"id":"scdb/1925-025","sc":1,"by":{"0":"34","1":"30"},"q":[{"src":"brief","b":0,"text":"choose the administrative rather than the judicial method of imposing","cite":"269 U.S. 304"}]},{"t":"case","label":"United States ex rel. Turner v. Williams","cite":"194 U.S. 279","y":1904,"id":"scdb/1903-104","sc":1,"by":{"0":"34","1":"28"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"by":{"0":"22","2":"5"},"q":[{"src":"brief","b":0,"text":"left within the discretion of the agencies to which Congress ha[s] confided the responsibility for substantive judgments.","cite":"435 U.S. 519, 524, 544"}]},{"t":"case","label":"Wellness International Network, Ltd. v. Sharif","cite":"575 U.S. 665","y":2015,"id":"2014/13-935","sc":1,"by":{"0":"30","1":"41, 42"},"q":[{"src":"brief","b":0,"text":"ha[s] the effect of lifting [any] ‘private rights’ bar","cite":"575 U.S. 665, 718"},{"src":"brief","b":1,"text":"the constitutionally assigned role of the federal judiciary.","cite":"575 U.S. at 678"}]},{"t":"case","label":"West v. Gibson","cite":"527 U.S. 212","y":1999,"id":"1998/98-238","sc":1,"by":{"0":"24"}},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"by":{"0":"34","1":"29","2":"17"},"q":[{"src":"argument","who":"Justice Barrett","text":"-- conditions that might be sort of mirror images of these, but -- but the point being, I mean, Oceanic Steam also says -- and I know part of this, like in Wong Wing, if you're talking about a misdemeanor -- take criminal law out of it."},{"src":"argument","who":"Justice Gorsuch","text":"I -- I thought Wong Wing said confiscating property goes to an Article III court for -- when you're trying to confiscate property from aliens."},{"src":"argument","who":"Ms. Harris","text":"Wong Wing does talk about also confiscating a property, but I don't think that can be fairly read to mean any civil penalties are out, or you would have to, I think, overrule Oceanic Steam and you would also have problems with, like, Murray's Lessee itself."}]},{"t":"case","label":"Zakonaite v. Wolf","cite":"226 U.S. 272","y":1912,"id":"scdb/1912-027","sc":1,"by":{"0":"34","1":"37"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"2, 17, 25, 45"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"2, 15-17, 23-25, 27, 30, 31, 35, 38, 45","1":"21, 25","2":"1, 3, 7, 21"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"0":"21, 27","2":"8"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(7)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"by":{"0":"11, 22, 22","2":"5"},"q":[{"src":"brief","b":0,"text":"agency process for the formulation of an order,","cite":"5 U.S.C. 551(7)"}]},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"11, 22"}},{"t":"usc","label":"5 U.S.C. § 555","url":"https://www.law.cornell.edu/uscode/text/5/555","stext":{"head":"§555. Ancillary matters","paras":[[0,"(a) This section applies, according to the provisions thereof, except as otherwise provided by this subchapter."],[0,"(b) A person compelled to appear in person before an agency or representative thereof is entitled to be accompanied, represented, and advised by counsel or, if permitted by the agency, by other qualified representative. A party is entitled to appear in person or by or with counsel or other duly qualified representative in an agency proceeding. So far as the orderly conduct of public business permits, an interested person may appear before an agency or its responsible employees for the presentation, adjustment, or determination of an issue, request, or controversy in a proceeding, whether interlocutory, summary, or otherwise, or in connection with an agency function. With due regard for the convenience and necessity of the parties or their representatives and within a reasonable time, each agency shall proceed to conclude a matter presented to it. This subsection does not grant or deny a person who is not a lawyer the right to appear for or represent others before an agency or in an agency proceeding."],[0,"(c) Process, requirement of a report, inspection, or other investigative act or demand may not be issued, made, or enforced except as authorized by law. A person compelled to submit data or evidence is entitled to retain or, on payment of lawfully prescribed costs, procure a copy or transcript thereof, except that in a nonpublic investigatory proceeding the witness may for good cause be limited to inspection of the official transcript of his testimony."],[0,"(d) Agency subpenas authorized by law shall be issued to a party on request and, when required by rules of procedure, on a statement or showing of general relevance and reasonable scope of the evidence sought. On contest, the court shall sustain the subpena or similar process or demand to the extent that it is found to be in accordance with law. In a proceeding for enforcement, the court shall issue an order requiring the appearance of the witness or the production of the evidence or data within a reasonable time under penalty of punishment for contempt in case of contumacious failure to comply."],[0,"(e) Prompt notice shall be given of the denial in whole or in part of a written application, petition, or other request of an interested person made in connection with any agency proceeding. Except in affirming a prior denial or when the denial is self-explanatory, the notice shall be accompanied by a brief statement of the grounds for denial."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/555?type=usc&year=mostrecent&link-type=html"},"by":{"0":"22","2":"5"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"0":"11"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)"],"by":{"0":"11"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(15)","(a)(15)(H)","(a)(15)(L)","(a)(15)(O)","(a)(15)(P)"],"by":{"0":"6, 7, 7, 7, 7, 7"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(n)(2)(C)","(t)(3)(C)"],"by":{"0":"44, 44"}},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(c)","(c)(1)","(c)(14)"],"stext":{"head":"§1184. Admission of nonimmigrants","paras":[[0,"(a) Regulations"],[0,"(1) The admission to the United States of any alien as a nonimmigrant shall be for such time and under such conditions as the Attorney General may by regulations prescribe, including when he deems necessary the giving of a bond with sufficient surety in such sum and containing such conditions as the Attorney General shall prescribe, to insure that at the expiration of such time or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States. No alien admitted to Guam or the Commonwealth of the Northern Mariana Islands without a visa pursuant to section 1182(l) of this title may be authorized to enter or stay in the United States other than in Guam or the Commonwealth of the Northern Mariana Islands or to remain in Guam or the Commonwealth of the Northern Mariana Islands for a period exceeding 45 days from date of admission to Guam or the Commonwealth of the Northern Mariana Islands. No alien admitted to the United States without a visa pursuant to section 1187 of this title may be authorized to remain in the United States as a nonimmigrant visitor for a period exceeding 90 days from the date of admission."],[0,"(2)(A) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(O) of this title shall be for such period as the Attorney General may specify in order to provide for the event (or events) for which the nonimmigrant is admitted."],[0,"(B) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(P) of this title shall be for such period as the Attorney General may specify in order to provide for the competition, event, or performance for which the nonimmigrant is admitted. In the case of nonimmigrants admitted as individual athletes under section 1101(a)(15)(P) of this title, the period of authorized status may be for an initial period (not to exceed 5 years) during which the nonimmigrant will perform as an athlete and such period may be extended by the Attorney General for an additional period of up to 5 years."],[0,"(b) Presumption of status; written waiver"],[0,"Every alien (other than a nonimmigrant described in subparagraph (L) or (V) of section 1101(a)(15) of this title, and other than a nonimmigrant described in any provision of section 1101(a)(15)(H)(i) of this title except subclause (b1) of such section) shall be presumed to be an immigrant until he establishes to the satisfaction of the consular officer, at the time of application for a visa, and the immigration officers, at the time of application for admission, that he is entitled to a nonimmigrant status under section 1101(a)(15) of this title. An alien who is an officer or employee of any foreign government or of any international organization entitled to enjoy privileges, exemptions, and immunities under the International Organizations Immunities Act [22 U.S.C. 288 et seq.], or an alien who is the attendant, servant, employee, or member of the immediate family of any such alien shall not be entitled to apply for or receive an immigrant visa, or to enter the United States as an immigrant unless he executes a written waiver in the same form and substance as is prescribed by section 1257(b) of this title."],[0,"(c) Petition of importing employer"],[0,"(1) The question of importing any alien as a nonimmigrant under subparagraph (H), (L), (O), or (P)(i) of section 1101(a)(15) of this title (excluding nonimmigrants under section 1101(a)(15)(H)(i)(b1) of this title) in any specific case or specific cases shall be determined by the Attorney General, after consultation with appropriate agencies of the Government, upon petition of the importing employer. Such petition, shall be made and approved before the visa is granted. The petition shall be in such form and contain such information as the Attorney General shall prescribe. The approval of such a petition shall not, of itself, be construed as establishing that the alien is a nonimmigrant. For purposes of this subsection with respect to nonimmigrants described in section 1101(a)(15)(H)(ii)(a) of this title, the term \"appropriate agencies of Government\" means the Department of Labor and includes the Department of Agriculture. The provisions of section 1188 of this title shall apply to the question of importing any alien as a nonimmigrant under section 1101(a)(15)(H)(ii)(a) of this title."],[0,"(2)(A) The Attorney General shall provide for a procedure under which an importing employer which meets requirements established by the Attorney General may file a blanket petition to import aliens as nonimmigrants described in section 1101(a)(15)(L) of this title instead of filing individual petitions under paragraph (1) to import such aliens. Such procedure shall permit the expedited processing of visas for admission of aliens covered under such a petition."],[0,"(B) For purposes of section 1101(a)(15)(L) of this title, an alien is considered to be serving in a capacity involving specialized knowledge with respect to a company if the alien has a special knowledge of the company product and its application in international markets or has an advanced level of knowledge of processes and procedures of the company."],[0,"(C) The Attorney General shall provide a process for reviewing and acting upon petitions under this subsection with respect to nonimmigrants described in section 1101(a)(15)(L) of this title within 30 days after the date a completed petition has been filed."],[0,"(D) The period of authorized admission for—"],[1,"(i) a nonimmigrant admitted to render services in a managerial or executive capacity under section 1101(a)(15)(L) of this title shall not exceed 7 years, or"],[1,"(ii) a nonimmigrant admitted to render services in a capacity that involves specialized knowledge under section 1101(a)(15)(L) of this title shall not exceed 5 years."],[0,"(E) In the case of an alien spouse admitted under section 1101(a)(15)(L) of this title, who is accompanying or following to join a principal alien admitted under such section, the Attorney General shall authorize the alien spouse to engage in employment in the United States and provide the spouse with an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(F) An alien who will serve in a capacity involving specialized knowledge with respect to an employer for purposes of section 1101(a)(15)(L) of this title and will be stationed primarily at the worksite of an employer other than the petitioning employer or its affiliate, subsidiary, or parent shall not be eligible for classification under section 1101(a)(15)(L) of this title if—"],[1,"(i) the alien will be controlled and supervised principally by such unaffiliated employer; or"],[1,"(ii) the placement of the alien at the worksite of the unaffiliated employer is essentially an arrangement to provide labor for hire for the unaffiliated employer, rather than a placement in connection with the provision of a product or service for which specialized knowledge specific to the petitioning employer is necessary."],[0,"(3) The Attorney General shall approve a petition—"],[1,"(A) with respect to a nonimmigrant described in section 1101(a)(15)(O)(i) of this title only after consultation in accordance with paragraph (6) or, with respect to aliens seeking entry for a motion picture or television production, after consultation with the appropriate union representing the alien's occupational peers and a management organization in the area of the alien's ability, or"],[1,"(B) with respect to a nonimmigrant described in section 1101(a)(15)(O)(ii) of this title after consultation in accordance with paragraph (6) or, in the case of such an alien seeking entry for a motion picture or television production, after consultation with such a labor organization and a management organization in the area of the alien's ability."],[0,"In the case of an alien seeking entry for a motion picture or television production, (i) any opinion under the previous sentence shall only be advisory, (ii) any such opinion that recommends denial must be in writing, (iii) in making the decision the Attorney General shall consider the exigencies and scheduling of the production, and (iv) the Attorney General shall append to the decision any such opinion. The Attorney General shall provide by regulation for the waiver of the consultation requirement under subparagraph (A) in the case of aliens who have been admitted as nonimmigrants under section 1101(a)(15)(O)(i) of this title because of extraordinary ability in the arts and who seek readmission to perform similar services within 2 years after the date of a consultation under such subparagraph. Not later than 5 days after the date such a waiver is provided, the Attorney General shall forward a copy of the petition and all supporting documentation to the national office of an appropriate labor organization."],[0,"(4)(A) For purposes of section 1101(a)(15)(P)(i)(a) of this title, an alien is described in this subparagraph if the alien—"],[1,"(i)(I) performs as an athlete, individually or as part of a group or team, at an internationally recognized level of performance;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1184?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8, 7, 44","1":"46"},"q":[{"src":"brief","b":0,"text":"upon petition of the importing employer.","cite":"8 U.S.C. 1184(c)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1188","url":"https://www.law.cornell.edu/uscode/text/8/1188","subs":["(a)(1)","(b)(2)","(b)(2)(B)","(c)(3)(A)","(g)(2)"],"stext":{"head":"§1188. Admission of temporary H–2A workers","paras":[[0,"(a) Conditions for approval of H–2A petitions"],[0,"(1) A petition to import an alien as an H–2A worker (as defined in subsection (i)(2)) may not be approved by the Attorney General unless the petitioner has applied to the Secretary of Labor for a certification that—"],[1,"(A) there are not sufficient workers who are able, willing, and qualified, and who will be available at the time and place needed, to perform the labor or services involved in the petition, and"],[1,"(B) the employment of the alien in such labor or services will not adversely affect the wages and working conditions of workers in the United States similarly employed."],[0,"(2) The Secretary of Labor may require by regulation, as a condition of issuing the certification, the payment of a fee to recover the reasonable costs of processing applications for certification."],[0,"(b) Conditions for denial of labor certification"],[0,"The Secretary of Labor may not issue a certification under subsection (a) with respect to an employer if the conditions described in that subsection are not met or if any of the following conditions are met:"],[1,"(1) There is a strike or lockout in the course of a labor dispute which, under the regulations, precludes such certification."],[1,"(2)(A) The employer during the previous two-year period employed H–2A workers and the Secretary of Labor has determined, after notice and opportunity for a hearing, that the employer at any time during that period substantially violated a material term or condition of the labor certification with respect to the employment of domestic or nonimmigrant workers."],[1,"(B) No employer may be denied certification under subparagraph (A) for more than three years for any violation described in such subparagraph."],[1,"(3) The employer has not provided the Secretary with satisfactory assurances that if the employment for which the certification is sought is not covered by State workers' compensation law, the employer will provide, at no cost to the worker, insurance covering injury and disease arising out of and in the course of the worker's employment which will provide benefits at least equal to those provided under the State workers' compensation law for comparable employment."],[1,"(4) The Secretary determines that the employer has not made positive recruitment efforts within a multi-state region of traditional or expected labor supply where the Secretary finds that there are a significant number of qualified United States workers who, if recruited, would be willing to make themselves available for work at the time and place needed. Positive recruitment under this paragraph is in addition to, and shall be conducted within the same time period as, the circulation through the interstate employment service system of the employer's job offer. The obligation to engage in positive recruitment under this paragraph shall terminate on the date the H–2A workers depart for the employer's place of employment."],[0,"(c) Special rules for consideration of applications"],[0,"The following rules shall apply in the case of the filing and consideration of an application for a labor certification under this section:"],[0,"(1) Deadline for filing applications"],[1,"The Secretary of Labor may not require that the application be filed more than 45 days before the first date the employer requires the labor or services of the H–2A worker."],[0,"(2) Notice within seven days of deficiencies"],[1,"(A) The employer shall be notified in writing within seven days of the date of filing if the application does not meet the standards (other than that described in subsection (a)(1)(A)) for approval."],[1,"(B) If the application does not meet such standards, the notice shall include the reasons therefor and the Secretary shall provide an opportunity for the prompt resubmission of a modified application."],[0,"(3) Issuance of certification"],[1,"(A) The Secretary of Labor shall make, not later than 30 days before the date such labor or services are first required to be performed, the certification described in subsection (a)(1) if—"],[2,"(i) the employer has complied with the criteria for certification (including criteria for the recruitment of eligible individuals as prescribed by the Secretary), and"],[2,"(ii) the employer does not actually have, or has not been provided with referrals of, qualified eligible individuals who have indicated their availability to perform such labor or services on the terms and conditions of a job offer which meets the requirements of the Secretary."],[1,"In considering the question of whether a specific qualification is appropriate in a job offer, the Secretary shall apply the normal and accepted qualifications required by non-H–2A-employers in the same or comparable occupations and crops."],[1,"(B)(i) For a period of 3 years subsequent to the effective date of this section, labor certifications shall remain effective only if, from the time the foreign worker departs for the employer's place of employment, the employer will provide employment to any qualified United States worker who applies to the employer until 50 percent of the period of the work contract, under which the foreign worker who is in the job was hired, has elapsed. In addition, the employer will offer to provide benefits, wages and working conditions required pursuant to this section and regulations."],[1,"(ii) The requirement of clause (i) shall not apply to any employer who—"],[2,"(I) did not, during any calendar quarter during the preceding calendar year, use more than 500 man-days of agricultural labor, as defined in section 203(u) of title 29,"],[2,"(II) is not a member of an association which has petitioned for certification under this section for its members, and"],[2,"(III) has not otherwise associated with other employers who are petitioning for temporary foreign workers under this section."],[1,"(iii) Six months before the end of the 3-year period described in clause (i), the Secretary of Labor shall consider the findings of the report mandated by section 403(a)(4)(D) of the Immigration Reform and Control Act of 1986 as well as other relevant materials, including evidence of benefits to United States workers and costs to employers, addressing the advisability of continuing a policy which requires an employer, as a condition for certification under this section, to continue to accept qualified, eligible United States workers for employment after the date the H–2A workers depart for work with the employer. The Secretary's review of such findings and materials shall lead to the issuance of findings in furtherance of the Congressional policy that aliens not be admitted under this section unless there are not sufficient workers in the United States who are able, willing, and qualified to perform the labor or service needed and that the employment of the aliens in such labor or services will not adversely affect the wages and working conditions of workers in the United States similarly employed. In the absence of the enactment of Federal legislation prior to three months before the end of the 3-year period described in clause (i) which addresses the subject matter of this subparagraph, the Secretary shall immediately publish the findings required by this clause, and shall promulgate, on an interim or final basis, regulations based on his findings which shall be effective no later than three years from the effective date of this section."],[1,"(iv) In complying with clause (i) of this subparagraph, an association shall be allowed to refer or transfer workers among its members: Provided, That for purposes of this section an association acting as an agent for its members shall not be considered a joint employer merely because of such referral or transfer."],[1,"(v) United States workers referred or transferred pursuant to clause (iv) of this subparagraph shall not be treated disparately."],[1,"(vi) An employer shall not be liable for payments under section 655.202(b)(6) of title 20, Code of Federal Regulations (or any successor regulation) with respect to an H–2A worker who is displaced due to compliance with the requirement of this subparagraph, if the Secretary of Labor certifies that the H–2A worker was displaced because of the employer's compliance with clause (i) of this subparagraph."],[1,"(vii)(I) No person or entity shall willfully and knowingly withhold domestic workers prior to the arrival of H–2A workers in order to force the hiring of domestic workers under clause (i)."],[1,"(II) Upon the receipt of a complaint by an employer that a violation of subclause (I) has occurred the Secretary shall immediately investigate. He shall within 36 hours of the receipt of the complaint issue findings concerning the alleged violation. Where the Secretary finds that a violation has occurred, he shall immediately suspend the application of clause (i) of this subparagraph with respect to that certification for that date of need."],[0,"(4) Housing"],[1,"Employers shall furnish housing in accordance with regulations. The employer shall be permitted at the employer's option to provide housing meeting applicable Federal standards for temporary labor camps or to secure housing which meets the local standards for rental and/or public accommodations or other substantially similar class of habitation: Provided, That in the absence of applicable local standards, State standards for rental and/or public accommodations or other substantially similar class of habitation shall be met: Provided further, That in the absence of applicable local or State standards, Federal temporary labor camp standards shall apply: Provided further, That the Secretary of Labor shall issue regulations which address the specific requirements of housing for employees principally engaged in the range production of livestock: Provided further, That when it is the prevailing practice in the area and occupation of intended employment to provide family housing, family housing shall be provided to workers with families who request it: And provided further, That nothing in this paragraph shall require an employer to provide or secure housing for workers who are not entitled to it under the temporary labor certification regulations in effect on June 1, 1986. The determination as to whether the housing furnished by an employer for an H–2A worker meets the requirements imposed by this paragraph must be made prior to the date specified in paragraph (3)(A) by which the Secretary of Labor is required to make a certification described in subsection (a)(1) with respect to a petition for the importation of such worker."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1188?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8, 8, 8, 8, 8","2":"16, 1, 3, 4-6"},"q":[{"src":"brief","b":0,"text":"petition to import an alien as an H–2A worker.","cite":"8 U.S.C. 1188(a)(1)"},{"src":"brief","b":0,"text":"take such actions * * * as may be necessary to assure employer compliance with terms and conditions of employment.","cite":"8 U.S.C. 1188(g)(2)"},{"src":"brief","b":2,"text":"as may be necessary to assure employer compliance.","cite":"8 U.S.C. 1188(g)(2)"},{"src":"brief","b":2,"text":"petition to import an alien as an H–2A worker","cite":"8 U.S.C. 1188(a)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1288","url":"https://www.law.cornell.edu/uscode/text/8/1288","subs":["(c)(4)(E)(i)"],"by":{"0":"44"}},{"t":"usc","label":"8 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/8/1321","by":{"0":"44"}},{"t":"usc","label":"8 U.S.C. § 1324a","url":"https://www.law.cornell.edu/uscode/text/8/1324a","subs":["(a)(1)","(e)(4)","(e)(3)(B)"],"by":{"0":"44, 44","2":"5"}},{"t":"usc","label":"8 U.S.C. § 1324c","url":"https://www.law.cornell.edu/uscode/text/8/1324c","by":{"0":"44"}},{"t":"law","label":"Pub. L. No. 99-603","url":"https://www.govinfo.gov/link/statute/100/3411","by":{"0":"7"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(3)"],"by":{"0":"8"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"0":"8"}},{"t":"usc","label":"15 U.S.C. § 77h-1","url":"https://www.law.cornell.edu/uscode/text/15/77h-1","subs":["(g)(1)"],"stext":{"head":"§77h–1. Cease-and-desist proceedings","paras":[[0,"(a) Authority of Commission"],[0,"If the Commission finds, after notice and opportunity for hearing, that any person is violating, has violated, or is about to violate any provision of this subchapter, or any rule or regulation thereunder, the Commission may publish its findings and enter an order requiring such person, and any other person that is, was, or would be a cause of the violation, due to an act or omission the person knew or should have known would contribute to such violation, to cease and desist from committing or causing such violation and any future violation of the same provision, rule, or regulation. Such order may, in addition to requiring a person to cease and desist from committing or causing a violation, require such person to comply, or to take steps to effect compliance, with such provision, rule, or regulation, upon such terms and conditions and within such time as the Commission may specify in such order. Any such order may, as the Commission deems appropriate, require future compliance or steps to effect future compliance, either permanently or for such period of time as the Commission may specify, with such provision, rule, or regulation with respect to any security, any issuer, or any other person."],[0,"(b) Hearing"],[0,"The notice instituting proceedings pursuant to subsection (a) shall fix a hearing date not earlier than 30 days nor later than 60 days after service of the notice unless an earlier or a later date is set by the Commission with the consent of any respondent so served."],[0,"(c) Temporary order"],[0,"(1) In general"],[1,"Whenever the Commission determines that the alleged violation or threatened violation specified in the notice instituting proceedings pursuant to subsection (a), or the continuation thereof, is likely to result in significant dissipation or conversion of assets, significant harm to investors, or substantial harm to the public interest, including, but not limited to, losses to the Securities Investor Protection Corporation, prior to the completion of the proceedings, the Commission may enter a temporary order requiring the respondent to cease and desist from the violation or threatened violation and to take such action to prevent the violation or threatened violation and to prevent dissipation or conversion of assets, significant harm to investors, or substantial harm to the public interest as the Commission deems appropriate pending completion of such proceeding. Such an order shall be entered only after notice and opportunity for a hearing, unless the Commission determines that notice and hearing prior to entry would be impracticable or contrary to the public interest. A temporary order shall become effective upon service upon the respondent and, unless set aside, limited, or suspended by the Commission or a court of competent jurisdiction, shall remain effective and enforceable pending the completion of the proceedings."],[0,"(2) Applicability"],[1,"This subsection shall apply only to a respondent that acts, or, at the time of the alleged misconduct acted, as a broker, dealer, investment adviser, investment company, municipal securities dealer, government securities broker, government securities dealer, or transfer agent, or is, or was at the time of the alleged misconduct, an associated person of, or a person seeking to become associated with, any of the foregoing."],[0,"(d) Review of temporary orders"],[0,"(1) Commission review"],[1,"At any time after the respondent has been served with a temporary cease-and-desist order pursuant to subsection (c), the respondent may apply to the Commission to have the order set aside, limited, or suspended. If the respondent has been served with a temporary cease-and-desist order entered without a prior Commission hearing, the respondent may, within 10 days after the date on which the order was served, request a hearing on such application and the Commission shall hold a hearing and render a decision on such application at the earliest possible time."],[0,"(2) Judicial review"],[1,"Within—"],[2,"(A) 10 days after the date the respondent was served with a temporary cease-and-desist order entered with a prior Commission hearing, or"],[2,"(B) 10 days after the Commission renders a decision on an application and hearing under paragraph (1), with respect to any temporary cease-and-desist order entered without a prior Commission hearing,"],[1,"the respondent may apply to the United States district court for the district in which the respondent resides or has its principal place of business, or for the District of Columbia, for an order setting aside, limiting, or suspending the effectiveness or enforcement of the order, and the court shall have jurisdiction to enter such an order. A respondent served with a temporary cease-and-desist order entered without a prior Commission hearing may not apply to the court except after hearing and decision by the Commission on the respondent's application under paragraph (1) of this subsection."],[0,"(3) No automatic stay of temporary order"],[1,"The commencement of proceedings under paragraph (2) of this subsection shall not, unless specifically ordered by the court, operate as a stay of the Commission's order."],[0,"(4) Exclusive review"],[1,"Section 77i(a) of this title shall not apply to a temporary order entered pursuant to this section."],[0,"(e) Authority to enter order requiring accounting and disgorgement"],[0,"In any cease-and-desist proceeding under subsection (a), the Commission may enter an order requiring accounting and disgorgement, including reasonable interest. The Commission is authorized to adopt rules, regulations, and orders concerning payments to investors, rates of interest, periods of accrual, and such other matters as it deems appropriate to implement this subsection."],[0,"(f) Authority of the Commission to prohibit persons from serving as officers or directors"],[0,"In any cease-and-desist proceeding under subsection (a), the Commission may issue an order to prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who has violated section 77q(a)(1) of this title or the rules or regulations thereunder, from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title, or that is required to file reports pursuant to section 78o(d) of this title, if the conduct of that person demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(g) Authority to impose money penalties"],[0,"(1) Grounds"],[1,"In any cease-and-desist proceeding under subsection (a), the Commission may impose a civil penalty on a person if the Commission finds, on the record, after notice and opportunity for hearing, that—"],[2,"(A) such person—"],[3,"(i) is violating or has violated any provision of this subchapter, or any rule or regulation issued under this subchapter; or"],[3,"(ii) is or was a cause of the violation of any provision of this subchapter, or any rule or regulation thereunder; and"],[2,"(B) such penalty is in the public interest."],[0,"(2) Maximum amount of penalty"],[0,"(A) First tier"],[2,"The maximum amount of a penalty for each act or omission described in paragraph (1) shall be $7,500 for a natural person or $75,000 for any other person."],[0,"(B) Second tier"],[2,"Notwithstanding subparagraph (A), the maximum amount of penalty for each such act or omission shall be $75,000 for a natural person or $375,000 for any other person, if the act or omission described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[0,"(C) Third tier"],[2,"Notwithstanding subparagraphs (A) and (B), the maximum amount of penalty for each such act or omission shall be $150,000 for a natural person or $725,000 for any other person, if—"],[3,"(i) the act or omission described in paragraph (1) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement; and"],[3,"(ii) such act or omission directly or indirectly resulted in—"],[4,"(I) substantial losses or created a significant risk of substantial losses to other persons; or"],[4,"(II) substantial pecuniary gain to the person who committed the act or omission."],[0,"(3) Evidence concerning ability to pay"],[1,"In any proceeding in which the Commission may impose a penalty under this section, a respondent may present evidence of the ability of the respondent to pay such penalty. The Commission may, in its discretion, consider such evidence in determining whether such penalty is in the public interest. Such evidence may relate to the extent of the ability of the respondent to continue in business and the collectability of a penalty, taking into account any other claims of the United States or third parties upon the assets of the respondent and the amount of the assets of the respondent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77h-1?type=usc&year=mostrecent&link-type=html"},"by":{"0":"21","1":"49"},"q":[{"src":"brief","b":1,"text":"on the record, after notice and an opportunity for a hearing.","cite":"15 U.S.C. § 77h-1(g)(1)"}]},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(d)(1)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)(3)(A)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","subs":["(a)(1)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","subs":["(i)(1)(A)"],"by":{"0":"21"}},{"t":"usc","label":"15 U.S.C. § 80b-9","url":"https://www.law.cornell.edu/uscode/text/15/80b-9","subs":["(e)(1)"],"by":{"0":"21"}},{"t":"usc","label":"19 U.S.C. § 1584","url":"https://www.law.cornell.edu/uscode/text/19/1584","by":{"0":"44"}},{"t":"usc","label":"20 U.S.C. § 1094","url":"https://www.law.cornell.edu/uscode/text/20/1094","by":{"0":"45"}},{"t":"usc","label":"26 U.S.C. § 6751","url":"https://www.law.cornell.edu/uscode/text/26/6751","by":{"0":"44"}},{"t":"usc","label":"28 U.S.C. § 2461","url":"https://www.law.cornell.edu/uscode/text/28/2461","subs":["(a)"],"stext":{"head":"§2461. Mode of recovery","paras":[[0,"(a) Whenever a civil fine, penalty or pecuniary forfeiture is prescribed for the violation of an Act of Congress without specifying the mode of recovery or enforcement thereof, it may be recovered in a civil action."],[0,"(b) Unless otherwise provided by Act of Congress, whenever a forfeiture of property is prescribed as a penalty for violation of an Act of Congress and the seizure takes place on the high seas or on navigable waters within the admiralty and maritime jurisdiction of the United States, such forfeiture may be enforced by libel in admiralty but in cases of seizures on land the forfeiture may be enforced by a proceeding by libel which shall conform as near as may be to proceedings in admiralty."],[0,"(c) If a person is charged in a criminal case with a violation of an Act of Congress for which the civil or criminal forfeiture of property is authorized, the Government may include notice of the forfeiture in the indictment or information pursuant to the Federal Rules of Criminal Procedure. If the defendant is convicted of the offense giving rise to the forfeiture, the court shall order the forfeiture of the property as part of the sentence in the criminal case pursuant to to 1 the Federal Rules of Criminal Procedure and section 3554 of title 18, United States Code. The procedures in section 413 of the Controlled Substances Act (21 U.S.C. 853) apply to all stages of a criminal forfeiture proceeding, except that subsection (d) of such section applies only in cases in which the defendant is convicted of a violation of such Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2461?type=usc&year=mostrecent&link-type=html"},"by":{"0":"23, 23","1":"50","2":"5"},"q":[{"src":"brief","b":0,"text":"Whenever a civil fine, penalty or pecuniary forfeiture is prescribed for the violation of an Act of Congress without specifying the mode of recovery or enforcement thereof, it may be recovered in a civil action.","cite":"28 U.S.C. 2461(a)"}]},{"t":"usc","label":"39 U.S.C. § 3018","url":"https://www.law.cornell.edu/uscode/text/39/3018","by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 1320a-7a","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7a","by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 1437z-1","url":"https://www.law.cornell.edu/uscode/text/42/1437z-1","by":{"0":"45"}},{"t":"usc","label":"47 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/47/503","subs":["(b)(4)","(b)(1)(B)"],"by":{"0":"22","2":"21"}},{"t":"usc","label":"47 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/47/504","subs":["(a)"],"by":{"0":"23","2":"5"}},{"t":"usc","label":"50 U.S.C. § 4812","url":"https://www.law.cornell.edu/uscode/text/50/4812","by":{"0":"44"}},{"t":"usc","label":"50 U.S.C. § 4819","url":"https://www.law.cornell.edu/uscode/text/50/4819","by":{"0":"44"}},{"t":"reg","label":"52 Fed. Reg. 20,524","url":"https://www.govinfo.gov/link/fr/52/20524","by":{"0":"22, 24","1":"8"}},{"t":"reg","label":"85 Fed. Reg. 13,186","url":"https://www.govinfo.gov/link/fr/85/13186","by":{"0":"11","1":"9"}},{"t":"case","label":"Arriaga v. Fla. Pac. Farms, LLC","cite":"305 F.3d 1228","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/305/1228/","by":{"1":"10"}},{"t":"case","label":"Atlas Roofing Co. v. OSHRC","cite":"430 U.S. 442","y":1977,"id":"1976/75-746","sc":1,"by":{"1":"16, 47","2":"22, 23"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"You gave up on Atlas -- Atlas Roofing in this case. But I looked at the terms and conditions. We keep talking about them as an employment contract almost, but this is the most unusual employment contract I've ever seen, although you do have terms on wages, terms on pest control, not charging people for -- certain amounts for things they buy."},{"src":"argument","who":"Justice Sotomayor","text":"But I go back to Atlas Roofing. This very much is more like safety and health regulation that really is not in the common law than it is a contract dispute."},{"src":"argument","who":"Ms. Harris","text":"So here is what I would say about Atlas Roofing. The reason we don't think that it's at issue in this case is because this case, unlike Atlas Roofing, involves historical areas of public rights."}]},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus., Inc.","cite":"575 U.S. 138","y":2015,"id":"2014/13-352","sc":1,"by":{"1":"22"}},{"t":"case","label":"Bank One Chi. NA v. Midwest Bank & Tr. Co.","cite":"516 U.S. 264","y":1996,"id":"1995/94-1175","sc":1,"by":{"1":"4, 16, 46, 47","2":"4"}},{"t":"case","label":"Bartlett v. Kane","cite":"57 U.S. 263","y":1854,"id":"scdb/1853-075","sc":1,"by":{"1":"38"}},{"t":"case","label":"Bates v. JPMorgan Chase Bank, NA","cite":"768 F.3d 1126","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/1126/","by":{"1":"20"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"1":"47","2":"3"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"by":{"1":"41, 42"}},{"t":"case","label":"Chauffeurs, Teamsters & Helpers, Loc. No. 391 v. Terry","cite":"494 U.S. 558","y":1990,"id":"1989/88-1719","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"an action for money damages was ‘the traditional form of relief offered in the courts of law.’","cite":"494 U.S. 558, 570"}]},{"t":"case","label":"Coit Indep. Joint Venture v. FSLIC","cite":"489 U.S. 561","y":1989,"id":"1988/87-996","sc":1,"by":{"1":"50"}},{"t":"case","label":"Coll. Sav. Bank v. Fla. Prepaid Postsecondary Educ. Expense Bd.","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"by":{"1":"16, 41, 42"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/103/","sc":1,"by":{"1":"44"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"597 U.S. 215","y":2022,"id":"2021/19-1392","sc":1,"by":{"1":"44"}},{"t":"case","label":"Donaldson v. DOL","cite":"930 F.2d 339","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/930/339/","by":{"1":"18, 20"}},{"t":"case","label":"Espinoza v. Mont. Dep’t of Revenue","cite":"591 U.S. 464","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/464/","sc":1,"by":{"1":"32"}},{"t":"case","label":"FCC v. AT&T","cite":"146 S. Ct. 1418","y":2026,"url":"https://www.courtlistener.com/c/S.%20Ct./146/1418/","sc":1,"by":{"1":"17, 22, 36, 37, 42, 48","2":"4, 5"}},{"t":"case","label":"Fla. Dept. of Health & Rehabilitative Servs. v. Fla. Nursing Home Ass’n","cite":"450 U.S. 147","y":1981,"id":"1980/80-532","sc":1,"by":{"1":"41"}},{"t":"case","label":"Garcia-Celestino v. Ruiz Harvesting Inc.","cite":"843 F.3d 1276","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/843/1276/","by":{"1":"18"}},{"t":"case","label":"Glidden Co. v. Zdanok","cite":"370 U.S. 530","y":1962,"id":"1961/242","sc":1,"by":{"1":"40"}},{"t":"case","label":"Gomez v. United States","cite":"490 U.S. 858","y":1989,"id":"1988/88-5014","sc":1,"by":{"1":"47"}},{"t":"case","label":"Granfinanciera, SA v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"by":{"1":"18","2":"9, 20"},"q":[{"src":"argument","who":"Ms. Harris","text":"And then the final limit I would just say is I think it is quite important and goes to Justice Alito's question, that the adjudication itself here involves federal enforcement of the conditions vis- -vis the employer in the program, and you're not taking the additional step of saying you're adjudicating essentially two private parties' rights in a final binding and conclusive way, the way you would be doing in, say, Granfinanciera or some of the bankruptcy cases that involved actually conclusively adjudicating a state law common --"}]},{"t":"case","label":"Great-W. Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"by":{"1":"23, 24"}},{"t":"case","label":"Hepner v. United States","cite":"213 U.S. 103","y":1909,"id":"scdb/1908-113","sc":1,"by":{"1":"3, 15, 27","2":"14"}},{"t":"case","label":"Intuit, Inc. v. FTC","cite":"170 F.4th 411","y":2026,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/170/411/","by":{"1":"25"}},{"t":"case","label":"Janus v. AFSCME","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"1":"44"}},{"t":"case","label":"Jarkesy v. SEC","cite":"34 F.4th 446","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/34/446/","by":{"1":"36, 47, 51"}},{"t":"case","label":"Koontz v. St. Johns River Water Management District","cite":"570 U.S. 595","y":2013,"id":"2012/11-1447","sc":1,"by":{"1":"42"}},{"t":"case","label":"Lopez v. Fish","cite":"2012 WL 2126856","y":2012,"court":"E.D. Tenn. May 21","by":{"1":"10"},"q":[{"src":"brief","b":1,"text":"federal cases too numerous to count which have held that H-2A workers may pursue state breach of contract claims against employers who fail to comply with clearance orders.","cite":"2012 WL 2126856"}]},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"by":{"1":"2, 35"}},{"t":"case","label":"Murray’s Lessee v. Hoboken Land & Improvement Co.","cite":"59 U.S. 272","y":1856,"id":"1850-1900/59us272","sc":1,"by":{"1":"39"}},{"t":"case","label":"Nieto-Santos v. Fletcher Farms","cite":"743 F.2d 638","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/743/638/","by":{"1":"7, 18"}},{"t":"case","label":"NLRB v. Jones & Laughlin Steel Corp.","cite":"301 U.S. 1","y":1937,"id":"1900-1940/301us1","sc":1,"by":{"1":"24"}},{"t":"case","label":"Ortiz v. United States","cite":"585 U.S. 427","y":2018,"id":"2017/16-1423","sc":1,"by":{"1":"40"}},{"t":"case","label":"Rosati v. Bos. Pipe Covering, Inc.","cite":"749 N.E.2d 143","y":2001,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/749/143/","by":{"1":"20"}},{"t":"case","label":"Rowe v. Grapevine Corp.","cite":"527 S.E.2d 814","y":1999,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E.2d/527/814/","by":{"1":"22"}},{"t":"case","label":"Salazar-Calderon v. Presidio Valley Farmers Ass’n","cite":"765 F.2d 1334","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/765/1334/","by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"the gravamen of appellants’ action is breach of employment contract.","cite":"765 F.2d 1334, 1353"}]},{"t":"case","label":"Solid Waste Agency v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"by":{"1":"47","2":"3"},"q":[{"src":"brief","b":1,"text":"[w]here an administrative interpretation of a statute invokes the outer limits of Congress’ power, we expect a clear indication that Congress intended that result.","cite":"531 U.S. 159, 172"}]},{"t":"case","label":"Southern Pacific Co. v. Denton","cite":"146 U.S. 202","y":1892,"id":"scdb/1892-019","sc":1,"by":{"1":"42"}},{"t":"case","label":"Sripetch v. SEC","cite":"146 S. Ct. 1403","y":2026,"id":"2025/25-466","sc":1,"by":{"1":"24"}},{"t":"case","label":"Stockwell v. United States","cite":"80 U.S. 531","y":1871,"id":"scdb/1871-053","sc":1,"by":{"1":"38"}},{"t":"case","label":"United States v. Regan","cite":"232 U.S. 37","y":1914,"id":"scdb/1913-285","sc":1,"by":{"1":"27"}},{"t":"case","label":"United States v. Sherman & Sons Co.","cite":"237 U.S. 146","y":1915,"id":"scdb/1914-070","sc":1,"by":{"1":"16, 38, 39, 46","2":"3, 16"}},{"t":"case","label":"United States v. Ward","cite":"309 F.2d 640","y":1962,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/309/640/","by":{"1":"32"}},{"t":"case","label":"Unitherm Food Sys., Inc. v. Swift-Eckrich, Inc.","cite":"546 U.S. 394","y":2006,"id":"2005/04-597","sc":1,"by":{"1":"35"}},{"t":"case","label":"W. Colo. Fruit Growers Ass’n v. Marshall","cite":"473 F. Supp. 693","y":1979,"court":"D. Colo.","url":"https://www.courtlistener.com/c/F.%20Supp./473/693/","by":{"1":"5, 7"},"q":[{"src":"brief","b":1,"text":"clearance order is essentially an offer for a contract of employment.","cite":"473 F. Supp. 693, 696"}]},{"t":"case","label":"Walker Process Equip. v. Food Mach. & Chem. Corp.","cite":"382 U.S. 172","y":1965,"id":"1965/13","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"enforcement of a patent obtained by fraud on the Patent Office.","cite":"382 U.S. 172, 173-74"},{"src":"argument","who":"Ms. Harris","text":"And then the third thing I would say is that there are also limits from the Due Process Clause. The Court's always recognized that in any form of adjudication, due process is going to be an important limit."}]},{"t":"case","label":"Williams v. United States","cite":"289 U.S. 553","y":1933,"id":"scdb/1932-134","sc":1,"by":{"1":"21, 39"}},{"t":"case","label":"Yamataya v. Fisher","cite":"189 U.S. 86","y":1903,"id":"scdb/1902-102","sc":1,"by":{"1":"28"}},{"t":"case","label":"Zuber v. Allen","cite":"396 U.S. 168","y":1969,"id":"1969/25","sc":1,"by":{"1":"51"},"q":[{"src":"brief","b":1,"text":"only one input in the interpretational equation.","cite":"396 U.S. 168, 192"}]},{"t":"usc","label":"5 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/5/554","subs":["(a)"],"by":{"1":"49","2":"5"}},{"t":"usc","label":"29 U.S.C. § 1853","url":"https://www.law.cornell.edu/uscode/text/29/1853","subs":["(b)(1)"],"by":{"1":"50"}},{"t":"usc","label":"31 U.S.C. § 3701","url":"https://www.law.cornell.edu/uscode/text/31/3701","subs":["(b)(1)"],"by":{"1":"22"}},{"t":"usc","label":"31 U.S.C. § 3711","url":"https://www.law.cornell.edu/uscode/text/31/3711","by":{"1":"22"}},{"t":"reg","label":"8 C.F.R. § 214.2","url":"https://www.ecfr.gov/current/title-8/section-214.2","subs":["(h)(5)"],"by":{"1":"7"}},{"t":"reg","label":"20 C.F.R. § 653.501","url":"https://www.ecfr.gov/current/title-20/section-653.501","subs":["(a)"],"by":{"1":"5"},"q":[{"src":"brief","b":1,"text":"place[s] [the] job order … into intrastate or interstate clearance.","cite":"20 C.F.R. § 653.501(a)"}]},{"t":"reg","label":"29 C.F.R. § 501.0","url":"https://www.ecfr.gov/current/title-29/section-501.0","by":{"1":"1, 8, 19"},"q":[{"src":"brief","b":1,"text":"cover the enforcement of all contractual obligations,","cite":"29 C.F.R. § 501.0"},{"src":"brief","b":1,"text":"cover the enforcement of all contractual obligations … applicable to the employment of H-2A workers and workers in corresponding employment.","cite":"29 C.F.R. § 501.0"}]},{"t":"reg","label":"80 Fed. Reg. 9482","url":"https://www.govinfo.gov/link/fr/80/9482","by":{"1":"20"}},{"t":"reg","label":"90 Fed. Reg. 28919","url":"https://www.govinfo.gov/link/fr/90/28919","by":{"1":"5, 6"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"by":{"2":"9, 11"},"q":[{"src":"brief","b":2,"text":"the liability of one individual to another,","cite":"285 U.S. 22, 51"},{"src":"brief","b":2,"text":"liability of one individual to another","cite":"285 U.S. at 51"}]},{"t":"case","label":"Crutcher v. Kentucky","cite":"141 U.S. 47","y":1891,"id":"scdb/1890-287","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"To carry on interstate commerce is not a franchise or a privilege.","cite":"141 U.S. 47, 57"}]},{"t":"case","label":"Horne v. Department of Agriculture","cite":"576 U.S. 351","y":2015,"id":"2014/14-275","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"not a special governmental benefit that the Government may hold hostage, to be ransomed by the waiver of constitutional protection.","cite":"576 U.S. 351, 366"}]},{"t":"case","label":"(I) Cases—Continued: Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/281/","sc":1,"by":{"2":"14"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"by":{"2":"9"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"2":"9"}},{"t":"case","label":"Porter v. Warner Holding Co.","cite":"328 U.S. 395","y":1946,"id":"scdb/1945-032","sc":1,"by":{"2":"6"}},{"t":"case","label":"South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"by":{"2":"20"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"primary purpose in restricting immigration is to preserve jobs for American workers,","cite":"467 U.S. 883, 893"}]},{"t":"case","label":"Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"cannot manufacture a new presumption now and retroactively impose it on a Congress that acted [40] years ago.","cite":"592 U.S. 43, 52"}]},{"t":"case","label":"Trump v. Slaughter","cite":"146 S. Ct. 2283","y":2026,"id":"2025/25-332","sc":1,"by":{"2":"8"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"5"}},{"t":"usc","label":"5 U.S.C. § 558","url":"https://www.law.cornell.edu/uscode/text/5/558","subs":["(b)"],"by":{"2":"5"}},{"t":"usc","label":"7 U.S.C. § 2021","url":"https://www.law.cornell.edu/uscode/text/7/2021","by":{"2":"20"}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","by":{"2":"20"}},{"t":"usc","label":"22 U.S.C. § 2278","url":"https://www.law.cornell.edu/uscode/text/22/2278","by":{"2":"19"}},{"t":"usc","label":"28 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/28/3101","by":{"2":"11"}}]};